def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker = next(v for v in Counter(v for row in grid for v in row) if v != background)
    out = [row[:] for row in grid]

    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
